<section class="page-hero small"><div class="container"><nav class="breadcrumbs"><a href="<?= e(url('service/'.$service['slug'])) ?>"><?= e($service['name']) ?></a><span>/</span><span>مركز الثقة</span></nav><span class="eyebrow">مركز الثقة</span><h1>كيف تحققنا من المعلومات؟</h1><p>المصدر وتاريخ التحقق والمسؤول وسجل التغييرات لكل خطوة.</p></div></section><section class="section"><div class="container trust-layout"><div><div class="trust-table-wrap"><table class="data-table"><thead><tr><th>الخطوة</th><th>الحالة</th><th>المصدر</th><th>آخر تحقق</th><th>المسؤول</th></tr></thead><tbody><?php foreach($steps as $s): ?><tr><td><?= e($s['title']) ?></td><td><span class="badge <?= $s['trust_status']==='verified'?'badge-success':'badge-warn' ?>"><?= $s['trust_status']==='verified'?'موثقة':'تحتاج تحقق' ?></span></td><td><?php if($s['source_url']): ?><a href="<?= e($s['source_url']) ?>" target="_blank" rel="noopener nofollow"><?= e($s['source_title'] ?: 'المصدر') ?></a><?php else: ?>—<?php endif; ?></td><td><?= e($s['verified_at'] ?: $s['source_verified_at'] ?: '—') ?></td><td><?= e($s['verified_by'] ?: $s['source_verified_by'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><div class="section-head compact top-gap"><div><span class="eyebrow">سجل التغييرات</span><h2>التغييرات المعتمدة</h2></div></div><?php if(!$changes): ?><div class="empty-state compact">لا توجد تغييرات معتمدة مسجلة بعد.</div><?php endif; ?><?php foreach($changes as $c): ?><div class="change-row"><time><?= e(substr($c['changed_at'],0,10)) ?></time><div><b><?= e($c['field_name']) ?></b><p><?= e($c['change_summary']) ?></p></div></div><?php endforeach; ?></div><aside><form class="form-card sticky-card" method="post" action="<?= e(url('trust/'.$service['slug'].'/report')) ?>"><?= csrf_field() ?><span class="eyebrow">ساعدنا على المراجعة</span><h3>الإبلاغ عن معلومة غير دقيقة</h3><p>البلاغ يدخل للمراجعة ولا يغير المحتوى المنشور تلقائيًا.</p><label>الخطوة (اختياري)<select name="step_id"><option value="">الخدمة بشكل عام</option><?php foreach($steps as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['title']) ?></option><?php endforeach; ?></select></label><label>ما المعلومة التي تحتاج مراجعة؟<textarea name="message" rows="6" required></textarea></label><button class="btn btn-primary" type="submit">إرسال البلاغ</button></form></aside></div></section>
